package com.rewang.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.io.*;import java.util.*;
/** Java native Android presentation client. Demo source is replaceable through ApiClient. */
public class MainActivity extends Activity {
 private LinearLayout content,nav;private JSONObject data;private final ApiClient api=new ApiClient();private String base="",token="",page="首页";private final Handler handler=new Handler(Looper.getMainLooper());private boolean live=false;private final String[] pages={"首页","分析中心","市场研究","投资组合","规则对照","交易账本","决策复盘","模型实验","AI研究","数据来源","连接设置"};
 protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_main);content=findViewById(R.id.content);nav=findViewById(R.id.navigation);findViewById(R.id.root).setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});for(String name:new String[]{"首页","行情","分析中心","投资组合","更多"}){Button b=new Button(this);b.setAllCaps(false);b.setText(name);b.setTextSize(11);b.setTextColor(0xff2d5366);b.setBackgroundColor(Color.TRANSPARENT);nav.addView(b,new LinearLayout.LayoutParams(0,-1,1));b.setOnClickListener(v->{if(name.equals("行情")){startActivity(new android.content.Intent(this,MarketActivity.class));}else if(name.equals("更多")){new AlertDialog.Builder(this).setTitle("研究目录").setItems(pages,(d,w)->show(pages[w])).show();}else show(name);});}loadDemo();}
 private void loadDemo(){try(InputStream in=getAssets().open("workspace-demo.json")){data=new JSONObject(read(in));live=false;((TextView)findViewById(R.id.mode)).setText("Java 原生 · 合成演示");show(page);}catch(Exception e){error(e.getMessage());}}
 private String read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}
 private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(5),1);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);t.setLayoutParams(p);content.addView(t);return t;}
 private void title(String s){text(s,27,0xff263e4e,true);}private void section(String s){View line=new View(this);line.setBackgroundColor(0xffddd5c9);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.topMargin=dp(16);p.bottomMargin=dp(22);content.addView(line,p);text(s,20,0xff263e4e,true);}private void body(String s){text(s,14,0xff60717b,false);}private void small(String s){text(s,12,0xff94765d,false);}private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(0xffffffff);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff2d5366));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.bottomMargin=dp(12);content.addView(b,p);b.setOnClickListener(v->r.run());}private void error(String s){new AlertDialog.Builder(this).setTitle("操作提示").setMessage(s).setPositiveButton("知道了",null).show();}
 private JSONArray array(String key){JSONArray a=data.optJSONArray(key);return a==null?new JSONArray():a;}private JSONObject research(){JSONObject r=data.optJSONObject("research");return r==null?new JSONObject():r;}private JSONArray series(){JSONArray a=research().optJSONArray("series");return a==null?new JSONArray():a;}private String num(JSONObject x,String k){return x==null||x.isNull(k)?"—":String.format(Locale.US,"%.2f",x.optDouble(k));}private String money(JSONObject x,String k){return x==null||x.isNull(k)?"—":String.format(Locale.US,"$%,.2f",x.optDouble(k)/100);}private JSONObject last(){JSONArray a=array("ledger");return a.optJSONObject(a.length()-1);}private void metric(String label,String value){text(label,12,0xff7c858a,false);text(value,25,0xff294c62,true);}private void chart(String key){ResearchChart c=new ResearchChart(this,series(),key);content.addView(c,new LinearLayout.LayoutParams(-1,dp(230)));body("图例：蓝 DEMO_A / 棕 DEMO_B / 绿 DEMO_C");}
 private void show(String name){page=name;content.removeAllViews();small("REWANG / ANDROID");title(name);for(int i=0;i<nav.getChildCount();i++){Button b=(Button)nav.getChildAt(i);b.setTextColor(b.getText().toString().equals(name)?0xffa26349:0xff65747b);}if(data==null)return;switch(name){case "首页":home();break;case "分析中心":analysis();break;case "市场研究":market();break;case "投资组合":portfolio();break;case "规则对照":compare();break;case "交易账本":ledger();break;case "决策复盘":journal();break;case "模型实验":models();break;case "AI研究":assistant();break;case "数据来源":sources();break;default:settings();}}
 private void home(){title("看见数据，\n也看见决定。");body("行情、交易与当时的想法，在同一条时间线上回看。");chart("index");section("当前研究资料");metric("合成标的 / 日报价",array("instruments").length()+" / "+array("prices").length());body("覆盖至 "+data.optString("asOf"));button("真实行情 · 历史回放 · 模拟投资",()->startActivity(new android.content.Intent(this,MarketActivity.class)));button("进入分析中心",()->show("分析中心"));button("查看投资组合",()->show("投资组合"));small("默认案例已填充；不代表真实证券表现。Android 为原生 View 与 Canvas，不使用 WebView。");}
 private void analysis(){body("跨标的收益、波动与回撤；指标来源于演示快照，真实模式由后端返回。");section("标准化走势 · 起点 100");chart("index");section("收益与风险");JSONArray a=series();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);text(x.optString("symbol"),17,0xff294c62,true);body("区间变化 "+num(x,"returnPct")+"%\n年化波动 "+num(x,"volatilityPct")+"% · 最大回撤 "+num(x,"maxDrawdownPct")+"%\n有效报价 "+x.optInt("observations")+" 条");}section("历史回撤");chart("drawdown");section("收益相关性");JSONArray c=research().optJSONArray("correlation");if(c!=null)for(int i=0;i<c.length();i++){JSONObject row=c.optJSONObject(i);JSONArray vs=row.optJSONArray("values");StringBuilder line=new StringBuilder(row.optString("symbol")+"\n");for(int j=0;vs!=null&&j<vs.length();j++){JSONObject v=vs.optJSONObject(j);line.append(v.optString("symbol")).append("  ").append(num(v,"value")).append(" · ").append(v.optInt("n")).append(" 对样本\n");}body(line.toString());}small("相关性不等于因果；波动按日收益样本标准差 × √252 计算。此版 Android 尚未提供日期筛选请求参数界面。");}
 private void market(){section("观察标的");JSONArray a=array("instruments");String[] options=new String[a.length()];for(int i=0;i<a.length();i++)options[i]=a.optJSONObject(i).optString("symbol");Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options));content.addView(spinner);LinearLayout target=new LinearLayout(this);target.setOrientation(1);content.addView(target);spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){target.removeAllViews();JSONArray prices=array("prices");StringBuilder s=new StringBuilder();int n=0;for(int j=prices.length()-1;j>=0&&n<12;j--){JSONObject q=prices.optJSONObject(j);if(options[position].equals(q.optString("symbol"))){s.append(q.optString("price_date")).append("   ").append(money(q,"close_minor")).append("\n\n");n++;}}TextView t=new TextView(MainActivity.this);t.setText(s);t.setTextSize(15);t.setPadding(0,dp(24),0,0);t.setTextColor(0xff40596a);target.addView(t);}});}
 private void portfolio(){JSONObject x=last();metric("账户总资产",money(x,"assetsMinor"));metric("累计净投入",money(x,"netContributionsMinor"));metric("累计盈亏",money(x,"pnlMinor"));metric("现金余额",money(x,"cashMinor"));section("持仓分布");JSONObject holdings=x==null?null:x.optJSONObject("holdings");if(holdings!=null){Iterator<String> keys=holdings.keys();while(keys.hasNext()){String s=keys.next();body(s+"     "+holdings.optInt(s)+" 份");}}button("查看完整账本",()->show("交易账本"));}
 private void compare(){JSONObject c=data.optJSONObject("comparison");section("同一笔资金，不同决策");if(c==null){body("暂无对照");return;}JSONArray actual=c.optJSONArray("actual"),baseline=c.optJSONArray("baseline");JSONObject a=actual==null?null:actual.optJSONObject(actual.length()-1),b=baseline==null?null:baseline.optJSONObject(baseline.length()-1);metric("实际决策路径",money(a,"assetsMinor"));metric("固定规则路径",money(b,"assetsMinor"));if(a!=null&&b!=null)metric("实际减固定规则",String.format(Locale.US,"$%,.2f",(a.optDouble("assetsMinor")-b.optDouble("assetsMinor"))/100));body("相同现金流，成交费用统一按 0.1% 重算。基准规则在入金后尽量买入整数份；不能作为未来收益保证。");}
 private void ledger(){section("交易记录");JSONArray a=array("trades");for(int i=a.length()-1;i>=0;i--){JSONObject t=a.optJSONObject(i);body(t.optString("effective_date")+" · "+t.optString("symbol")+"\n"+(t.optString("side").equals("buy")?"买入":"卖出")+" "+t.optInt("quantity")+" 份 × "+money(t,"price_minor"));}section("资金流水");JSONArray f=array("flows");for(int i=0;i<f.length();i++){JSONObject x=f.optJSONObject(i);body(x.optString("effective_date")+" · "+x.optString("kind")+" · "+money(x,"amount_minor"));}small("当前 Android 账本为读取界面；增改删接口按 docs/ANDROID_HANDOFF.md 对接，尚未迁移 Web 编辑器。");}
 private void journal(){button("写一条演示笔记",()->{if(live){error("真实模式的笔记写入需队友接入 POST /api/workspace");return;}EditText input=new EditText(this);input.setMinLines(3);new AlertDialog.Builder(this).setTitle("记录决策理由").setView(input).setPositiveButton("保存",(d,w)->{if(input.getText().toString().trim().isEmpty()){error("理由不能为空");return;}try{JSONObject n=new JSONObject();n.put("reason",input.getText());n.put("expectation","");n.put("review","");array("notes").put(n);show(page);}catch(Exception e){error(e.getMessage());}}).setNegativeButton("取消",null).show();});JSONArray a=array("notes");for(int i=0;i<a.length();i++){JSONObject n=a.optJSONObject(i);section("决策记录 "+(i+1));body(n.optString("reason"));if(!n.optString("expectation").isEmpty())body("预期："+n.optString("expectation"));body(n.optString("review").isEmpty()?"待复盘":"复盘："+n.optString("review"));}}
 private void models(){small("模拟实验 · 不执行模型训练");section("实验配置");Spinner model=new Spinner(this);model.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"逻辑回归","随机森林"}));content.addView(model);for(String s:new String[]{"过去 5 日收益","20 日波动率","均线偏离率"}){CheckBox box=new CheckBox(this);box.setText(s);box.setChecked(true);content.addView(box);}body("时间划分：训练 60% → 验证 20% → 测试 20%。严格按时间先后，避免未来信息泄漏。");TextView state=text("已有演示评估，运行可观察加载状态。",13,0xff94765d,false);button("运行模拟实验",()->{state.setText("模拟运行中…");handler.postDelayed(()->state.setText("演示流程完成；下方为固定样例，非当前配置训练结果。"),1200);});section("评估结果 · 50 条固定样例");metric("Accuracy / F1","64.00% / 66.67%");body("Precision 69.23% · Recall 64.29%\nTP 18 · TN 14 · FP 8 · FN 10\n始终预测上涨基线：56.00%");small("真实实验接口由后端实现；模型概率不等于预测准确率。");}
 private void assistant(){small("AI 研究 · 演示响应，未调用大模型");section("研究摘要");body("资金投入与投资盈利应分开观察。结合最大回撤和波动率判断风险，再以同一现金流的规则路径检查决策差异。");EditText question=new EditText(this);question.setHint("询问当前组合的收益与风险…");question.setMinLines(2);content.addView(question);TextView answer=text("来源：合成行情、交易与资金流水。",14,0xff40596a,false);button("发送演示问题",()->{String q=question.getText().toString().trim();if(q.isEmpty()){error("请先输入问题");return;}answer.setText("生成演示响应中…");handler.postDelayed(()->answer.setText("【模拟响应】关于“"+q+"”：当前案例包含 "+array("instruments").length()+" 个标的。期末资产 "+money(last(),"assetsMinor")+"，净投入 "+money(last(),"netContributionsMinor")+"。请结合回撤、波动和交易依据复盘。本回答由模板生成，未进行真实模型推理。"),700);});small("DeepSeek 密钥只放后端，Android 不读取电脑上的密钥文件，也不内置 API key。");}
 private void sources(){metric("日报价总数",String.valueOf(array("prices").length()));JSONArray a=array("instruments");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);section(x.optString("symbol")+" · "+x.optString("name"));body("来源："+x.optString("source")+"\n口径："+x.optString("price_type"));}small("CSV 上传和校验界面当前保留在 Web 参考端；Android 迁移尚未完成。");}
 private void settings(){body("演示模式可直接浏览。真实模式需要后端返回与 workspace-demo.json 同结构的 JSON。");EditText address=new EditText(this);address.setHint("https://your-backend.example");address.setText(base);address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);content.addView(address);EditText bearer=new EditText(this);bearer.setHint("后端签发的用户 Access Token（不是大模型 key）");bearer.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);content.addView(bearer);button("连接后端并读取账户",()->{base=address.getText().toString().trim();token=bearer.getText().toString().trim();api.request(base,"/api/workspace","GET",token,null,(result,error)->{if(error!=null){error(error);return;}if(!result.has("instruments")||!result.has("ledger")){error("后端响应缺少 workspace 字段");return;}data=result;live=true;((TextView)findViewById(R.id.mode)).setText("原生客户端 · 后端连接");show("首页");});});button("恢复合成演示数据",this::loadDemo);small("Access Token 仅留内存；需由队友接入登录、续期和权限校验。当前没有真实用户登录功能。");}
 protected void onDestroy(){handler.removeCallbacksAndMessages(null);api.close();super.onDestroy();}
}
